/**
 * DirectionStepCard — single turn-by-turn instruction card.
 *
 * Displays a direction step with icon, instruction text, distance, and
 * duration.  State-based accent coloring:
 *   - default    → normal surface styling
 *   - active     → accent border highlight
 *   - accessible → success accent (for elevator/ramp segments)
 *   - stairs     → warning accent (for stairs steps)
 *   - arrived    → green highlight for the final destination step
 *
 * DirectionStep typed from mobile/domain/navGraph.ts.
 *
 * Usage:
 *   <DirectionStepCard
 *     step={step}
 *     isActive={index === currentStepIndex}
 *     onPress={() => onStepPress(index)}
 *   />
 */

import { Pressable, StyleSheet, Text, View } from 'react-native';
import { useTheme } from '../../theme';
import { DirectionStep, StepIcon } from '../../domain/navGraph';

export interface DirectionStepCardProps {
  /** The direction step to display. */
  step: DirectionStep;
  /** Highlight the card when this step is the active guidance step. */
  isActive?: boolean;
  /** Called when the user taps the card. */
  onPress?: () => void;
  /** Optional extra styles applied to the card container. */
  style?: object;
}

// ─── Icon helpers ─────────────────────────────────────────────────────────────

const STEP_ICONS: Record<string, string> = {
  'straight': '↑',
  'turn-left': '←',
  'turn-right': '→',
  'sharp-left': '↙',
  'sharp-right': '↘',
  'arrive': '🏁',
  'accessible': '♿',
  'stairs-up': '⬆',
  'stairs-down': '⬇',
  'elevator': '🛗',
  'ramp': '♿',
};

function stepIconEmoji(icon: StepIcon): string {
  return STEP_ICONS[icon] ?? '→';
}

// ─── Distance / duration formatting ────────────────────────────────────────────

/**
 * Format normalized distance as a human-readable string.
 * 1 normalized unit ≈ 50 m.
 */
function formatDistance(norm: number): string {
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)}km`;
  return `${meters}m`;
}

/** Format seconds as a human-readable duration string. */
function formatDuration(seconds: number): string {
  if (seconds < 60) return `${seconds}s`;
  const mins = Math.floor(seconds / 60);
  const secs = seconds % 60;
  if (secs === 0) return `${mins}min`;
  return `${mins}min ${secs}s`;
}

// ─── Accent variant ───────────────────────────────────────────────────────────

type AccentVariant = 'default' | 'active' | 'accessible' | 'stairs' | 'arrived';

function accentVariant(step: DirectionStep, isActive?: boolean): AccentVariant {
  if (step.icon === 'arrive') return 'arrived';
  if (isActive) return 'active';
  if (step.icon === 'elevator' || step.icon === 'ramp') return 'accessible';
  if (step.icon === 'stairs-up' || step.icon === 'stairs-down') return 'stairs';
  return 'default';
}

// ─── Component ────────────────────────────────────────────────────────────────

export function DirectionStepCard({
  step,
  isActive = false,
  onPress,
  style,
}: DirectionStepCardProps) {
  const { colors } = useTheme();

  const variant = accentVariant(step, isActive);

  const borderColor =
    variant === 'arrived'
      ? colors.success
      : variant === 'active'
        ? colors.borderAccent
        : variant === 'accessible'
          ? colors.success
          : variant === 'stairs'
            ? colors.warning
            : colors.guidanceCardBorder;

  const iconBgColor =
    variant === 'arrived'
      ? colors.successSubtle
      : variant === 'accessible'
        ? colors.successSubtle
        : variant === 'stairs'
          ? colors.warning + '33'  // warning with alpha
          : colors.guidanceStepIcon;

  const iconColor =
    variant === 'arrived'
      ? colors.success
      : variant === 'accessible'
        ? colors.success
        : variant === 'stairs'
          ? colors.warning
          : colors.accent;

  const cardBg =
    variant === 'arrived'
      ? colors.successSubtle
      : colors.guidanceCard;

  const textColor =
    variant === 'arrived'
      ? colors.successMuted
      : variant === 'active'
        ? colors.textPrimary
        : colors.textSecondary;

  const distanceColor =
    variant === 'arrived'
      ? colors.success
      : variant === 'accessible'
        ? colors.successMuted
        : variant === 'stairs'
          ? colors.warningMuted
          : colors.accent;

  const icon = stepIconEmoji(step.icon);
  const distance = formatDistance(step.distanceM);
  const duration = formatDuration(step.durationSec);

  const CardWrapper = onPress ? Pressable : View;

  return (
    <CardWrapper
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`${step.instruction}, ${distance}, ${duration}`}
      accessibilityHint="Tap to highlight this step on the map"
      style={({ pressed }: { pressed: boolean }) => [
        styles.card,
        {
          backgroundColor: cardBg,
          borderColor,
          borderWidth: variant === 'default' ? 1 : 1.5,
        },
        pressed && onPress && styles.cardPressed,
        style,
      ]}
      testID={`direction-step-card-${step.icon}`}
    >
      {/* Icon container */}
      <View
        style={[
          styles.iconContainer,
          { backgroundColor: iconBgColor },
        ]}
      >
        <Text style={[styles.icon, { color: iconColor }]}>{icon}</Text>
      </View>

      {/* Instruction + meta */}
      <View style={styles.content}>
        <Text
          style={[styles.instruction, { color: textColor }]}
          numberOfLines={2}
        >
          {step.instruction}
        </Text>
        <View style={styles.metaRow}>
          <Text style={[styles.metaText, { color: distanceColor }]}>
            {distance}
          </Text>
          <Text style={[styles.metaDot, { color: colors.textDisabled }]}>·</Text>
          <Text style={[styles.metaText, { color: colors.textMuted }]}>
            {duration}
          </Text>
          {step.isAccessibleSegment && (
            <>
              <Text style={[styles.metaDot, { color: colors.textDisabled }]}>·</Text>
              <Text style={[styles.metaText, { color: colors.success }]}>
                ♿ Accessible
              </Text>
            </>
          )}
        </View>
      </View>

      {/* Floor badge */}
      <View
        style={[styles.floorBadge, { backgroundColor: colors.guidanceFloorBadge }]}
      >
        <Text style={[styles.floorBadgeText, { color: colors.textInverse }]}>
          {step.floorNumber}
        </Text>
      </View>
    </CardWrapper>
  );
}

// ─── Styles ─────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  card: {
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: 12,
    padding: 12,
    gap: 12,
    marginVertical: 3,
  },
  cardPressed: {
    opacity: 0.8,
  },
  iconContainer: {
    width: 40,
    height: 40,
    borderRadius: 10,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  icon: {
    fontSize: 20,
  },
  content: {
    flex: 1,
    gap: 3,
  },
  instruction: {
    fontSize: 14,
    fontWeight: '600',
    lineHeight: 20,
  },
  metaRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 4,
  },
  metaText: {
    fontSize: 12,
    fontWeight: '500',
  },
  metaDot: {
    fontSize: 12,
  },
  floorBadge: {
    width: 28,
    height: 28,
    borderRadius: 6,
    alignItems: 'center',
    justifyContent: 'center',
    flexShrink: 0,
  },
  floorBadgeText: {
    fontSize: 12,
    fontWeight: '700',
  },
});

/**
 * RoutePathOverlay — renders the computed route path on top of the floor plan image.
 *
 * View-based polyline (no new SVG dependency). For each adjacent pair of
 * nodes on the active floor, renders endpoint dots and a connecting line
 * rotated to match the bearing.
 */

import { StyleSheet, View } from 'react-native';
import { ViewportDimensions } from '../../map/mapTransform';

/* ─── Types ─── */

export interface RoutePathPoint {
  x: number;       // normalized [0,1]
  y: number;       // normalized [0,1]
  floorId: number;
}

interface Props {
  path: RoutePathPoint[];
  activeFloorId: number;
  viewport: ViewportDimensions;
  scale: number;
}

/* ─── Helpers (pure, no closure state) ─── */

function segmentBearingDeg(
  from: RoutePathPoint,
  to: RoutePathPoint,
  vp: ViewportDimensions,
  sc: number,
): number {
  const dx = (to.x - from.x) * vp.width * sc;
  const dy = (to.y - from.y) * vp.height * sc;
  return Math.atan2(dy, dx) * (180 / Math.PI);
}

function segmentLen(
  from: RoutePathPoint,
  to: RoutePathPoint,
  vp: ViewportDimensions,
  sc: number,
): number {
  const dx = (to.x - from.x) * vp.width * sc;
  const dy = (to.y - from.y) * vp.height * sc;
  return Math.hypot(dx, dy);
}

/* ─── Coordinate to pixel position ─── */

function toPixel(node: RoutePathPoint, vp: ViewportDimensions, sc: number) {
  return {
    left: node.x * vp.width * sc - 4,
    top:  node.y * vp.height * sc - 4,
  };
}

/* ─── Component ─── */

export function RoutePathOverlay({ path, activeFloorId, viewport, scale }: Props) {
  const floorNodes = path.filter(n => n.floorId === activeFloorId);

  if (floorNodes.length === 0) return null;

  // Single node → draw one dot
  if (floorNodes.length === 1) {
    const { left, top } = toPixel(floorNodes[0], viewport, scale);
    return <View style={[styles.dot, styles.dotStart, { left, top }]} />;
  }

  // Multiple nodes → draw start/end dots + connecting segments
  return (
    <View style={styles.overlay} pointerEvents="none">
      {/* Start dot */}
      <View style={[styles.dot, styles.dotStart, toPixel(floorNodes[0], viewport, scale)]} />

      {/* Segments between consecutive nodes */}
      {floorNodes.slice(1).map((toNode, i) => {
        const fromNode = floorNodes[i];
        const { left: startLeft, top: startTop } = toPixel(fromNode, viewport, scale);
        const { left: endLeft, top: endTop } = toPixel(toNode, viewport, scale);
        const len = segmentLen(fromNode, toNode, viewport, scale);
        const angleDeg = segmentBearingDeg(fromNode, toNode, viewport, scale);

        return (
          <View key={`seg-${i}`} style={styles.overlay} pointerEvents="none">
            {/* Connecting line (anchored at start, rotated) */}
            {len > 0 && (
              <View
                style={[
                  styles.line,
                  { width: len, left: startLeft + 4, top: startTop + 3, transform: [{ rotate: `${angleDeg}deg` }] },
                ]}
              />
            )}
          </View>
        );
      })}

      {/* End dot */}
      <View style={[styles.dot, styles.dotEnd, toPixel(floorNodes[floorNodes.length - 1], viewport, scale)]} />
    </View>
  );
}

/* ─── Styles ─── */

const styles = StyleSheet.create({
  overlay: {
    ...StyleSheet.absoluteFillObject,
  },
  dot: {
    position: 'absolute',
    width: 8,
    height: 8,
    borderRadius: 4,
    backgroundColor: '#38bdf8',
  },
  dotStart: {
    backgroundColor: '#4ade80',
  },
  dotEnd: {
    backgroundColor: '#f87171',
  },
  line: {
    position: 'absolute',
    height: 2,
    backgroundColor: '#38bdf8',
    transformOrigin: 'left center',
  },
});

/**
 * ConfidenceIndicator — colored dot + optional detail popover.
 *
 * Renders a small (12×12px) filled circle whose color reflects the
 * current GPS/heading confidence level.  Tapping the dot toggles a
 * small inline label showing the level name.
 */

import { useState } from 'react';
import { Pressable, StyleSheet, Text, View } from 'react-native';

import { ConfidenceLevel } from '../../routing/guidanceState';

export { ConfidenceLevel } from '../../routing/guidanceState';

// ─── Color map ────────────────────────────────────────────────────────────────

const DOT_COLOR: Record<ConfidenceLevel, string> = {
  high: '#22c55e',   // green
  medium: '#eab308', // yellow
  low: '#f97316',    // orange
  none: '#ef4444',   // red
};

const LABEL_COLOR: Record<ConfidenceLevel, string> = {
  high: '#4ade80',
  medium: '#facc15',
  low: '#fb923c',
  none: '#f87171',
};

const LABEL_TEXT: Record<ConfidenceLevel, string> = {
  high: 'GPS OK',
  medium: 'Heading?',
  low: 'Weak GPS',
  none: 'No GPS',
};

const ICON_MAP: Record<ConfidenceLevel, string> = {
  high: '',
  medium: '',
  low: '',
  none: '⚠',
};

interface Props {
  confidence: ConfidenceLevel;
}

export function ConfidenceIndicator({ confidence }: Props) {
  const [showLabel, setShowLabel] = useState(false);

  const dotColor = DOT_COLOR[confidence];
  const labelColor = LABEL_COLOR[confidence];
  const labelText = LABEL_TEXT[confidence];
  const icon = ICON_MAP[confidence];

  return (
    <Pressable
      style={styles.container}
      onPress={() => setShowLabel(s => !s)}
      accessibilityRole="button"
      accessibilityLabel={`GPS confidence: ${confidence}`}
      testID="confidence-indicator"
    >
      <View style={[styles.dot, { backgroundColor: dotColor }]}>
        {icon ? <Text style={styles.icon}>{icon}</Text> : null}
      </View>
      {showLabel && (
        <View style={[styles.labelBadge, { backgroundColor: dotColor + '33', borderColor: dotColor }]}>
          <Text style={[styles.labelText, { color: labelColor }]}>
            {labelText}
          </Text>
        </View>
      )}
    </Pressable>
  );
}

const styles = StyleSheet.create({
  container: {
    alignItems: 'center',
    justifyContent: 'center',
  },
  dot: {
    width: 12,
    height: 12,
    borderRadius: 9999,
    alignItems: 'center',
    justifyContent: 'center',
  },
  icon: {
    fontSize: 7,
    color: '#fff',
    lineHeight: 9,
  },
  labelBadge: {
    position: 'absolute',
    top: 16,
    left: '50%',
    transform: [{ translateX: -30 }],
    width: 60,
    borderWidth: 1,
    borderRadius: 6,
    paddingHorizontal: 6,
    paddingVertical: 3,
    alignItems: 'center',
  },
  labelText: {
    fontSize: 10,
    fontWeight: '600',
  },
});

/**
 * LiveGuidanceOverlay — real-time guidance overlay driven by GuidanceState.
 *
 * Conditionally renders one of five UI variants based on `guidanceState.phase`:
 * - `idle`          → nothing
 * - `low-confidence` → orange banner prompting position confirmation
 * - `guiding`       → step card with instruction, icon, distance, progress
 * - `rerouting`     → blue banner with spinner
 * - `arrived`       → green celebration card
 */

import { ActivityIndicator, Pressable, StyleSheet, Text, View } from 'react-native';
import { useRef, useState } from 'react';

import { getActiveStep, GuidanceState } from '../../routing/guidanceState';
import { DirectionStep, NormalizedFloorRecord } from '../../domain/navGraph';
import { ConfidenceIndicator, ConfidenceLevel } from './ConfidenceIndicator';

// ─── Step icon helpers (mirrors RoutePreview) ────────────────────────────────

const STEP_ICONS: Record<string, string> = {
  'straight': '↑',
  'turn-left': '←',
  'turn-right': '→',
  'sharp-left': '↙',
  'sharp-right': '↘',
  'arrive': '🏁',
  'accessible': '♿',
  'stairs-up': '⬆',
  'stairs-down': '⬇',
  'elevator': '🛗',
  'ramp': '♿',
};

function stepIcon(step: DirectionStep): string {
  return STEP_ICONS[step.icon] ?? '→';
}

// ─── Distance formatting ─────────────────────────────────────────────────────

/**
 * Format a normalized distance as a human-readable string.
 * Normalized coordinate space → approximate real distance (50 m per unit).
 */
function formatDistance(norm: number): string {
  const meters = Math.round(norm * 50);
  if (meters < 1) return '<1m';
  if (meters >= 1000) return `${(meters / 1000).toFixed(1)}km`;
  return `${meters}m`;
}

/**
 * Sum of distances for all steps from currentStepIndex onward.
 */
function remainingDistance(state: GuidanceState): number {
  const { route, currentStepIndex } = state;
  if (route.phase !== 'ready' || !route.directions) return 0;
  return route.directions.steps
    .slice(currentStepIndex)
    .reduce((sum, s) => sum + s.distanceM, 0);
}

// ─── Props ───────────────────────────────────────────────────────────────────

export interface LiveGuidanceOverlayProps {
  guidanceState: GuidanceState;
  onConfirmPosition: () => void;
  onStopGuidance: () => void;
  /** Floor ID of the current snapped position. */
  floorId?: number | null;
  /** Floor lookup map for display labels. */
  floorMap?: Map<number, NormalizedFloorRecord>;
  /** When true, applies accessible mode styling to elevator/ramp steps. */
  accessibleMode?: boolean;
}

// ─── Sub-components ───────────────────────────────────────────────────────────

/** Low-confidence banner: orange/yellow background, confirm button. */
function LowConfidenceBanner({
  onConfirmPosition,
  floorId,
  floorMap,
}: {
  onConfirmPosition: () => void;
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
}) {
  const floorLabel = floorId && floorMap ? floorMap.get(floorId)?.floor.floorNumber ?? floorId : null;

  return (
    <View style={styles.lowConfidenceBanner} testID="low-confidence-banner">
      <View style={styles.bannerRow}>
        <ConfidenceIndicator confidence="low" />
        <Text style={styles.lowConfidenceText}>
          Can't confirm your location.{'\n'}
          Tap the map to confirm where you are, or move to an open area.
          {floorLabel != null ? `\nYou are on Floor ${floorLabel}.` : ''}
        </Text>
      </View>
      <Pressable style={styles.confirmButton} onPress={onConfirmPosition} testID="confirm-position-btn">
        <Text style={styles.confirmButtonText}>Confirm location</Text>
      </Pressable>
    </View>
  );
}

/** Rerouting banner: blue background with spinner. */
function ReroutingBanner() {
  return (
    <View style={styles.reroutingBanner} testID="rerouting-banner">
      <ActivityIndicator color="#38bdf8" size="small" />
      <Text style={styles.reroutingText}>Recalculating your route...</Text>
    </View>
  );
}

/** Main guiding card: step instruction, icon, distance, progress. */
function GuidingCard({
  state,
  onStopGuidance,
  floorId,
  floorMap,
  accessibleMode,
}: {
  state: GuidanceState;
  onStopGuidance: () => void;
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
  accessibleMode?: boolean;
}) {
  const activeStep = getActiveStep(state);
  const { route, currentStepIndex, positionConfidence } = state;

  const totalSteps = route.phase === 'ready' && route.directions
    ? route.directions.steps.length
    : 0;
  const progressLabel = `Step ${currentStepIndex + 1} of ${totalSteps}`;
  const remaining = remainingDistance(state);

  const isAccessibleStep = activeStep?.icon === 'elevator' || activeStep?.icon === 'ramp';
  const highlightAccessible = accessibleMode && isAccessibleStep;

  let instruction = activeStep?.instruction ?? 'Navigating...';
  if (highlightAccessible) {
    instruction = `${instruction} (accessible)`;
  }

  const icon = activeStep ? stepIcon(activeStep) : '→';

  return (
    <View style={styles.guidingCard} testID="guiding-card">
      {/* Top row: step icon + instruction */}
      <View style={styles.stepRow}>
        <View style={[styles.stepIconContainer, highlightAccessible && styles.stepIconContainerAccessible]}>
          <Text style={[styles.stepIcon, highlightAccessible && styles.stepIconAccessible]}>{icon}</Text>
        </View>
        <Text style={styles.instructionText} numberOfLines={2}>
          {instruction}
        </Text>
        <ConfidenceIndicator confidence={positionConfidence} />
      </View>

      {/* Floor badge row */}
      <FloorBadge floorId={floorId} floorMap={floorMap} />

      {/* Bottom row: distance + progress + end button */}
      <View style={styles.bottomRow}>
        <Text style={styles.distanceText}>{formatDistance(remaining)} remaining</Text>
        <Text style={styles.progressText}>{progressLabel}</Text>
        <Pressable onPress={onStopGuidance} testID="stop-guidance-btn">
          <Text style={styles.endButton}>End guidance</Text>
        </Pressable>
      </View>
    </View>
  );
}

/** Arrived celebration card. */
function ArrivedCard({
  state,
  onStopGuidance,
}: {
  state: GuidanceState;
  onStopGuidance: () => void;
}) {
  const destLabel =
    state.route.phase === 'ready' && state.route.destination
      ? state.route.destination.label
      : 'Destination';

  return (
    <View style={styles.arrivedCard} testID="arrived-card">
      <Text style={styles.checkmark}>✅</Text>
      <Text style={styles.arrivedTitle}>You've arrived!</Text>
      <Text style={styles.arrivedDest}>{destLabel}</Text>
      <Pressable style={styles.doneButton} onPress={onStopGuidance} testID="done-btn">
        <Text style={styles.doneButtonText}>Done</Text>
      </Pressable>
    </View>
  );
}

/** Floor badge — shows current floor label next to step icon in the guiding card. */
function FloorBadge({
  floorId,
  floorMap,
}: {
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
}) {
  if (!floorId || !floorMap) return null;
  const record = floorMap.get(floorId);
  if (!record) return null;
  return (
    <View style={styles.floorBadge} testID="floor-badge">
      <Text style={styles.floorBadgeText}>Floor {record.floor.floorNumber}</Text>
    </View>
  );
}

/** Floor transition banner — briefly shown for 2500 ms when floor changes. */
function FloorTransitionBanner({
  floorId,
  floorMap,
}: {
  floorId?: number | null;
  floorMap?: Map<number, NormalizedFloorRecord>;
}) {
  const prevFloorIdRef = useRef<number | null>(null);
  const [visible, setVisible] = useState(false);
  const [displayFloorId, setDisplayFloorId] = useState<number | null>(null);

  const safeFloorId: number | null = floorId ?? null;

  if (safeFloorId !== null && safeFloorId !== prevFloorIdRef.current && prevFloorIdRef.current !== null) {
    prevFloorIdRef.current = safeFloorId;
    const label = floorMap?.get(safeFloorId)?.floor.floorNumber ?? safeFloorId;
    setDisplayFloorId(safeFloorId);
    setVisible(true);
    setTimeout(() => setVisible(false), 2500);
  } else if (safeFloorId !== null) {
    prevFloorIdRef.current = safeFloorId;
  }

  if (!visible || displayFloorId === null) return null;

  const label = floorMap?.get(displayFloorId)?.floor.floorNumber ?? displayFloorId;

  return (
    <View style={styles.floorTransitionBanner} testID="floor-transition-banner">
      <Text style={styles.floorTransitionText}>Now on Floor {label}</Text>
    </View>
  );
}

// ─── Main component ──────────────────────────────────────────────────────────

export function LiveGuidanceOverlay({
  guidanceState,
  onConfirmPosition,
  onStopGuidance,
  floorId,
  floorMap,
  accessibleMode,
}: LiveGuidanceOverlayProps) {
  const { phase } = guidanceState;

  if (phase === 'idle') return null;

  if (phase === 'low-confidence') {
    return <LowConfidenceBanner onConfirmPosition={onConfirmPosition} floorId={floorId} floorMap={floorMap} />;
  }

  if (phase === 'rerouting') {
    return <ReroutingBanner />;
  }

  if (phase === 'arrived') {
    return <ArrivedCard state={guidanceState} onStopGuidance={onStopGuidance} />;
  }

  // phase === 'guiding'
  return (
    <>
      <FloorTransitionBanner floorId={floorId} floorMap={floorMap} />
      <GuidingCard
        state={guidanceState}
        onStopGuidance={onStopGuidance}
        floorId={floorId}
        floorMap={floorMap}
        accessibleMode={accessibleMode}
      />
    </>
  );
}

// ─── Styles ──────────────────────────────────────────────────────────────────

const styles = StyleSheet.create({
  // Low-confidence banner
  lowConfidenceBanner: {
    backgroundColor: '#7c2d12',
    borderColor: '#f97316',
    borderWidth: 1,
    borderRadius: 12,
    padding: 14,
    margin: 12,
    gap: 10,
  },
  bannerRow: {
    flexDirection: 'row',
    alignItems: 'flex-start',
    gap: 10,
  },
  lowConfidenceText: {
    flex: 1,
    color: '#fed7aa',
    fontSize: 13,
    lineHeight: 18,
  },
